#!/usr/bin/env python3
"""Apply the final E181 canon audit without changing production task acceptance."""
from pathlib import Path
import json
R=Path(__file__).resolve().parents[1]
p=R/'specs/taskgraph/v1/tasks/catalogue-source-inventory.json'
s=p.read_text().replace('Retain message, part, attachment, author, timestamp, access, and source-to-object relation IDs.','Retain opaque source/part/attachment aliases, authorized source-to-object relations and minimum approved metadata only; no raw bodies, original bytes or source filenames.')
s=s.replace('Implement JNY-R04 final-paper gating: explicit Finish review for matching document/source followed by a later canonical print snapshot; keep queue/provider receipt separate.','Implement JNY-R04 final-paper gating: new/replacement Finish review requires an available source and matching document/source reference; a matching accepted review survives transient byte expiry. A later canonical print snapshot is required; keep queue/provider receipt separate.')
s=s.replace('JNY-R04 has missing-source, stale-review, finish, later-print, queue failure/retry and no-final-shortcut tests.','JNY-R04 tests unavailable source blocking new/replacement review, accepted-review survival after byte expiry, document/source invalidation, finish, later print, queue failure/retry and no-final shortcut.')
json.loads(s);p.write_text(s)
p=R/'notes/THE-JOURNEYS-SPEC.md';s=p.read_text().replace('**Finish review** is disabled until matching source/document state is ready. A later canonical print is still required for **Final paper**.','A new/replacement **Finish review** requires matching available source/document state. Session byte expiry does not revoke an accepted review whose durable source reference and document fingerprint still match. Replacement source or material document edit invalidates that acceptance. A later canonical print is still required for **Final paper**.');p.write_text(s)
p=R/'notes/THE-IMPLEMENTATION-BANK.md';s=p.read_text()
s=s.replace('### Source conversation membership and capability are separate proofs\n','### Source conversation membership and capability are separate proofs\n\n> E181 supersedes the raw-message persistence below. THE-SOURCE-PRIVACY-SPEC is authoritative: external custody, transient body/attachment reads and opaque membership references; persist reviewed business facts and capability/receipt metadata only.\n') if '> E181 supersedes the raw-message persistence below.' not in s else s
s=s.replace('### §163 · Catalogue imports are a transition, not an AI conversion\n','### §163 · Catalogue imports are a transition, not an AI conversion\n\n> E181 supersedes this historical raw-asset/unknown-cell storage design. THE-SOURCE-PRIVACY-SPEC and THE-CATALOGUE-CONTRACT-SPEC require external originals, session-only parsing and reviewed business fields. Never recreate durable raw files, filenames or arbitrary columns from this older proposal.\n') if '> E181 supersedes this historical raw-asset/unknown-cell storage design.' not in s else s
p.write_text(s)
p=R/'notes/THE-SYSTEM-SPEC.md';s=p.read_text();heading='### CUS-01.5 · Working copy'
if heading not in s:s+='\n\n'+heading+'\n\nUse **Open chat**, **Send email**, **Call** or **Open conversation** for the one main channel action. History rows open the selected conversation. Customer sections are **Pricing**, **Frequent products**, **Upcoming**, **History**, **Insights**, visible **Delivery**/**Account**, **Delivery changes** and **Concerns**. Expanded insights use **Order value**, **Order summary** and **Patterns**. Window/count labels are concise (`Last 5 albaranes`, `12 months`); methodology and architecture stay in documentation. Empty state: **No concerns.** There is no Contact them/Write to them pair, founder narration, or Customer details & history disclosure.\n'
p.write_text(s)
